      { topic: "Sự phát triển của cây con", type: "tf", q: "Cây con chỉ có thể mọc lên từ hạt.", a: false, x: "Ngoài hạt, nhiều cây còn cho cây con mọc ra từ đoạn thân, từ rễ hay từ lá của cây mẹ.", lv: 1 },
      { topic: "Sự phát triển của cây con", type: "mc", q: "Khi trồng sắn, người ta chặt thân sắn thành từng đoạn ngắn, mỗi đoạn có vài mắt (chỗ hơi lồi lên trên thân). Vì sao đoạn thân phải có mắt?", o: ["Vì chồi non và rễ mới sẽ mọc ra từ các mắt", "Vì mắt giúp đoạn thân nặng, cắm chắc hơn", "Vì mắt là nơi chứa hạt của cây sắn", "Vì mắt giúp đoạn thân không bị khô héo"], x: "Chồi non và rễ mới mọc ra từ các mắt trên đoạn thân, rồi lớn dần thành cây sắn con.", lv: 3 },
      { topic: "Sinh sản của động vật", type: "mc", q: "Con vật nào dưới đây đẻ con?", o: ["Con thỏ", "Con vịt", "Con rùa", "Con cá chép"], x: "Thỏ đẻ con; vịt, rùa, cá chép đẻ trứng.", lv: 1 },
      { topic: "Vòng đời của động vật", type: "mc", q: "Vịt con mới nở đã lạch bạch đi theo vịt mẹ. So với vịt trưởng thành, vịt con:", o: ["Có hình dạng gần giống, chỉ nhỏ hơn và phủ lông tơ", "Trông khác hẳn, giống như một con sâu nhỏ", "Phải ở yên trong vỏ trứng thêm vài tuần nữa", "Không bao giờ lớn bằng vịt trưởng thành"], x: "Vịt đẻ trứng; vịt con nở ra từ trứng đã có hình dạng gần giống vịt trưởng thành, lớn dần lên thành vịt trưởng thành.", lv: 2 },
      { topic: "Vòng đời của động vật", type: "num", q: "Trứng ruồi nở sau khoảng 1 ngày; từ khi nở, phải thêm khoảng 9 ngày nữa mới thành ruồi trưởng thành. Một đống rác bị ruồi đẻ trứng vào ngày 2 tháng 7 mà không được dọn đi. Khoảng ngày nào của tháng 7 thì những con ruồi mới từ đống rác đó bay ra?", ans: 12, x: "Ngày 2 + 1 ngày + 9 ngày: 2 + 1 + 9 = 12. Khoảng ngày 12 tháng 7, ruồi mới từ đống rác đó bay ra.", lv: 3 }
